import functools

def solve_game(n, is_alice_turn):
    state = [0] * n

    @functools.lru_cache(None)
    def get_result(current_state, turn):
        # current_state is a tuple of 0s and 1s
        # turn: 0 for Alice (max), 1 for Bob (min)

        # Find all possible moves
        possible_moves = []
        for i in range(n - 1):
            if current_state[i] == 0 and current_state[i+1] == 0:
                possible_moves.append(i)

        if not possible_moves:
            # Game ends, count uncovered squares
            return sum(1 for x in current_state if x == 0)

        if turn == 0: # Alice's turn (maximize u)
            best_val = -1
            for move in possible_moves:
                next_state = list(current_state)
                next_state[move] = 1
                next_state[move+1] = 1
                val = get_result(tuple(next_state), 1)
                if val > best_val:
                    best_val = val
            return best_val
        else: # Bob's turn (minimize u)
            best_val = float('inf')
            for move in possible_moves:
                next_state = list(current_state)
                next_state[move] = 1
                next_state[move+1] = 1
                val = get_result(tuple(next_state), 0)
                if val < best_val:
                    best_val = val
            return best_val

    return get_result(tuple(state), 0)

