import functools

def solve_game(n):
    @functools.lru_cache(None)
    def get_result(current_state, turn):
        # Find all possible moves
        possible_moves = []
        for i in range(n - 1):
            if current_state[i] == 0 and current_state[i+1] == 0:
                possible_moves.append(i)

        if not possible_moves:
            return sum(1 for x in current_state if x == 0)

        if turn == 0: # Alice (max)
            return max(get_result(tuple(set_state(current_state, move)), 1) for move in possible_moves)
        else: # Bob (min)
            return min(get_result(tuple(set_state(current_state, move)), 0) for move in possible_moves)

    def set_state(current_state, move):
        s = list(current_state)
        s[move] = 1
        s[move+1] = 1
        return s

    return get_result(tuple([0]*n), 0)

