import functools

@functools.lru_cache(None)
def get_result(segments, turn):
    # segments is a tuple of lengths of empty segments, sorted
    # turn: 0 for Alice (max), 1 for Bob (min)

    possible_moves = []
    # A move consists of choosing a segment of length k >= 2 and splitting it
    # into segments of length i and k-i-2, where 0 <= i <= k-2.
    for idx, k in enumerate(segments):
        if k >= 2:
            for i in range(k - 1):
                # A tile covers squares (i+1, i+2) in the segment (1-indexed)
                # It splits the segment into one of length i and one of length k-i-2.
                # The split happens at index i+1 and i+2.
                # The remaining parts are length i and k - (i+2).
                new_segments = list(segments)
                new_segments.pop(idx)
                if i > 0:
                    new_segments.append(i)
                if k - i - 2 > 0:
                    new_segments.append(k - i - 2)
                possible_moves.append(tuple(sorted(new_segments)))

    if not possible_moves:
        # The total number of uncovered squares is the sum of segments’ lengths
        # if no more moves are possible. But a move is possible if any segment length >= 2.
        # So if no more moves are possible, all segments must be length 0 or 1.
        return sum(segments)

    if turn == 0: # Alice
        return max(get_result(move, 1) for move in possible_moves)
    else: # Bob
        return min(get_result(move, 0) for move in possible_moves)

